<?php

namespace Modules\Support\Http\Requests;

use Illuminate\Foundation\Http\FormRequest;
use Illuminate\Validation\Rule;
use Knuckles\Scribe\Attributes\BodyParam;
use Modules\Support\Enums\DevicePlatform;

#[BodyParam('device_identifier', 'string', 'Stable per-install device identifier generated by the app (max 255).', example: 'b3f1c2d4-5e6f-7a8b-9c0d-e1f2a3b4c5d6')]
#[BodyParam('platform', 'string', 'Device platform.', enum: DevicePlatform::class, example: 'ios')]
#[BodyParam('fcm_token', 'string', 'Firebase Cloud Messaging token for push (max 1024); null when push is not granted.', required: false, nullable: true, example: 'fcm-token-abc123')]
#[BodyParam('locale', 'string', 'Preferred locale for push (`en` or `ar`, max 10).', required: false, nullable: true, example: 'ar')]
class LaunchDeviceRequest extends FormRequest
{
    public function authorize(): bool
    {
        return true;
    }

    /**
     * @return array<string, array<int, mixed>>
     */
    public function rules(): array
    {
        return [
            'device_identifier' => ['required', 'string', 'max:255'],
            'platform' => ['required', Rule::enum(DevicePlatform::class)],
            'fcm_token' => ['nullable', 'string', 'max:1024'],
            'locale' => ['nullable', 'string', 'max:10'],
        ];
    }
}
